<script lang="ts">
  let {entity, connections=[]}=$props();
  let depth=$state(1);
  let showLabels=$state(true);
  let selected=$state<any>(null);
  const W=1000,H=590,cx=500,cy=295;
  const visible=$derived(connections.slice(0,36));
  function parse(raw:any){try{return raw?JSON.parse(String(raw)):{};}catch{return {};}}
  function kind(c:any){const m=parse(c.connected_metadata_json);if(c.connected_gets_rfx_entity_id)return 'tender';if(c.connected_gets_supplier_entity_id)return 'supplier';if(m?.gets?.kind==='agency')return 'agency';if(String(c.connected_slug??'').startsWith('charities-officer-'))return 'person';return String(c.connected_type||'other');}
  function label(c:any){return String(c.connected_name||'Record').replace(/^Supplier record — /,'').replace(/ — RFx .*$/,'').replace(/^Procurement record RFx [^—]+ — /,'');}
  function pos(i:number,n:number){const ring=i%2;const count=Math.ceil(n/2);const j=Math.floor(i/2);const a=(j/Math.max(count,1))*Math.PI*2-(Math.PI/2)+(ring*.16);const rx=ring?390:245,ry=ring?225:155;return{x:cx+Math.cos(a)*rx,y:cy+Math.sin(a)*ry};}
  function fill(k:string){return k==='charity'?'#69c48d':k==='person'?'#73a9e6':k==='tender'?'#e5b65f':k==='supplier'?'#c58be2':k==='agency'?'#62c8c3':k==='company'?'#ef8e78':'#9aa7a2';}
  function short(s:string,n=28){return s.length>n?s.slice(0,n-1)+'…':s;}
</script>
<section class="graph-section">
  <div class="graph-head"><div><p class="eyebrow">Relationship explorer</p><h2>Graph view</h2></div><div class="view-note">{visible.length} of {connections.length} direct connections shown</div></div>
  <div class="graph-shell">
    <aside class="legend"><strong>Legend</strong><span><i style="background:#69c48d"></i>Charity</span><span><i style="background:#73a9e6"></i>Officer / person</span><span><i style="background:#e5b65f"></i>Government tender</span><span><i style="background:#c58be2"></i>GETS supplier</span><span><i style="background:#62c8c3"></i>Government agency</span><span><i style="background:#ef8e78"></i>Company</span></aside>
    <div class="canvas">
      {#if connections.length===0}<div class="graph-empty">No connections are currently loaded for this record.</div>{:else}
      <svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label={`Relationship graph for ${entity.canonical_name}`}>
        {#each visible as c,i}{@const p=pos(i,visible.length)}<line x1={cx} y1={cy} x2={p.x} y2={p.y}/>{/each}
        {#each visible as c,i}{@const p=pos(i,visible.length)}{@const k=kind(c)}<g class="node" role="link" tabindex="0" onclick={()=>selected=c} onkeydown={(e)=>{if(e.key==='Enter')selected=c}}><circle cx={p.x} cy={p.y} r="10" fill={fill(k)}/>{#if showLabels}<text x={p.x} y={p.y+24} text-anchor="middle">{short(label(c))}</text>{/if}</g>{/each}
        <g class="center"><circle cx={cx} cy={cy} r="22"/><circle cx={cx} cy={cy} r="30" class="halo"/><text x={cx} y={cy+48} text-anchor="middle">{short(entity.canonical_name,38)}</text></g>
      </svg>{/if}
      <div class="zoom-hint">Scroll/drag interactions will come with the full graph engine</div>
    </div>
    <aside class="controls"><strong>View</strong><label><span>Depth</span><select bind:value={depth} disabled><option value={1}>1 hop</option></select></label><label class="check"><input type="checkbox" bind:checked={showLabels}/> Labels</label><p>This preview shows direct, evidence-backed relationships already loaded for this record.</p></aside>
  </div>
  {#if selected}<div class="selection"><div><small>Selected connection</small><strong>{label(selected)}</strong><span>{String(selected.predicate).replaceAll('_',' ')} · {kind(selected)}</span></div><a href={`/record/${selected.connected_id}`}>Open record →</a><button onclick={()=>selected=null} aria-label="Close selection">×</button></div>{/if}
  <p class="graph-disclaimer"><strong>What does a connection mean?</strong> Lines show relationships found in public records. A connection does not by itself imply wrongdoing, influence or endorsement. Check the record's source evidence for context.</p>
</section>
<style>
.graph-section{margin-top:38px}.graph-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:12px}.graph-head h2{font-family:Georgia,'Times New Roman',serif;font-size:30px;margin:2px 0}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:#176b5a;font-weight:700;margin:0}.view-note{font-size:12px;color:#68726e}.graph-shell{position:relative;display:grid;grid-template-columns:155px minmax(0,1fr) 165px;min-height:590px;background:#111817;border:1px solid #293532;overflow:hidden}.canvas{position:relative;min-width:0;background:radial-gradient(circle at 50% 50%,#1c2a27 0,#111817 58%,#0c1211 100%);border-left:1px solid #293532;border-right:1px solid #293532}.canvas:before{content:'';position:absolute;inset:0;background-image:radial-gradient(#40514d 1px,transparent 1px);background-size:24px 24px;opacity:.22}.canvas svg{position:relative;width:100%;height:590px;display:block}.canvas line{stroke:#5d706b;stroke-width:1;opacity:.62}.canvas text{fill:#dfe9e5;font:12px Arial,Helvetica,sans-serif;paint-order:stroke;stroke:#111817;stroke-width:4px;stroke-linejoin:round}.node{cursor:pointer}.node circle{stroke:#e7efec;stroke-width:1.5}.node:hover circle{stroke-width:4}.center circle:first-child{fill:#3da978;stroke:#dff7eb;stroke-width:2}.center .halo{fill:none;stroke:#3da978;stroke-width:2;opacity:.28}.center text{font-weight:700;font-size:14px}.legend,.controls{z-index:2;color:#cbd8d3;padding:18px 14px;font-size:11px;background:#101715}.legend strong,.controls strong{display:block;color:#fff;text-transform:uppercase;letter-spacing:.08em;font-size:10px;margin-bottom:16px}.legend span{display:flex;align-items:center;gap:8px;margin:10px 0}.legend i{width:9px;height:9px;border-radius:50%;display:inline-block}.controls label{display:flex;flex-direction:column;gap:6px;margin:12px 0;color:#9eada8}.controls select{background:#192320;border:1px solid #34433f;color:#dce7e3;padding:7px}.controls .check{flex-direction:row;align-items:center}.controls p{line-height:1.5;color:#82918c;margin-top:20px}.zoom-hint{position:absolute;bottom:10px;left:50%;transform:translateX(-50%);font-size:10px;color:#65746f;white-space:nowrap}.graph-empty{position:absolute;inset:0;display:grid;place-items:center;color:#93a19c;font-size:13px}.selection{display:flex;align-items:center;gap:18px;background:#fff;border:1px solid #d5dad6;border-top:0;padding:14px 18px}.selection div{display:flex;flex-direction:column;gap:3px;flex:1}.selection small,.selection span{font-size:11px;color:#68726e}.selection a{font-weight:700;font-size:13px}.selection button{border:0;background:none;font-size:24px;color:#68726e;cursor:pointer}.graph-disclaimer{font-size:12px;line-height:1.5;color:#59635f;margin:12px 0 0}.graph-disclaimer strong{color:#202624;margin-right:4px}@media(max-width:800px){.graph-shell{grid-template-columns:1fr;min-height:auto}.legend,.controls{display:none}.canvas{border:0}.canvas svg{height:480px}.view-note{display:none}}@media(max-width:520px){.canvas svg{height:400px}.selection{align-items:flex-start;flex-wrap:wrap}.zoom-hint{display:none}}
</style>